// The Error Trigger receives one item describing the failed execution.
// Shape: { execution: { id, url, error, lastNodeExecuted, mode, retryOf }, workflow: { id, name } }
// A workflow that fails before any node runs (e.g. a bad trigger) sends { trigger: { error } } instead.
const payload = $input.first().json;

const workflow = payload.workflow || {};
const execution = payload.execution || {};
const trigger = payload.trigger || {};
const error = execution.error || trigger.error || {};

const failedNode =
  (error.node && error.node.name) || execution.lastNodeExecuted || 'trigger / before first node';

const message = error.message || 'No error message was supplied by n8n';
const description = error.description || null;

// The item that was in flight when the node threw. n8n puts it on the error
// context when it is available; it is the single most useful thing in the alert.
const context = error.context || {};
const inputItem = context.itemIndex !== undefined
  ? { item_index: context.itemIndex, data: context.data || null }
  : null;

const excerpt = JSON.stringify(inputItem || context || {}).slice(0, 1500);

const lines = [
  ':boom: *n8n workflow failed*',
  '• Workflow: *' + (workflow.name || 'unknown') + '*  (`' + (workflow.id || 'unknown') + '`)',
  '• Failing node: *' + failedNode + '*',
  '• Error: ' + message,
];
if (description) lines.push('• Detail: ' + description);
lines.push('• Mode: ' + (execution.mode || 'unknown'));
if (execution.retryOf) lines.push('• This was a retry of execution ' + execution.retryOf);
lines.push('• Execution: ' + (execution.url || 'not available (manual execution)'));
lines.push('• Item in flight: `' + excerpt.slice(0, 900) + '`');

return [
  {
    json: {
      workflow_id: workflow.id || null,
      workflow_name: workflow.name || null,
      execution_id: execution.id || null,
      execution_url: execution.url || null,
      failed_node: failedNode,
      error_name: error.name || 'Error',
      error_message: message,
      error_description: description,
      error_stack: (error.stack || '').slice(0, 2000) || null,
      execution_mode: execution.mode || null,
      retry_of: execution.retryOf || null,
      input_excerpt: excerpt,
      occurred_at: new Date().toISOString(),
      slack_text: lines.join('\n'),
    },
  },
];
